code='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row}
    marker = min(colors, key=lambda v: sum(row.count(v) for row in grid))
    # Fill gaps between consecutive markers along each row and column.
    for r in range(h):
        positions = [c for c, v in enumerate(grid[r]) if v == marker]
        for a, b in zip(positions, positions[1:]):
            for c in range(a + 1, b):
                out[r][c] = 3
    for c in range(w):
        positions = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(positions, positions[1:]):
            for r in range(a + 1, b):
                out[r][c] = 3
    return out
'''
